        term BGP-AOS-Policy-${TENANT_TAG}-60 {
            from {
                protocol evpn;
                route-filter 0::0/0 prefix-length-range /128-/128;
            }
            then {
                community add $TENANT_COMMUNITY_V6;
                accept;
            }
        }
        term BGP-AOS-Policy-${TENANT_TAG}-100 {
            then reject;
        }
    }
}

