firewall {
    family inet {
        filter MX_TLB_LB_TRUST {
            term NAPT44_tlb_traffic {
                from {
                    source-address {
                        $SFW_CLIENT_PFX;
                    }
                }
                then {
                    count NAPT44_tlb_forward_traffic;
                    routing-instance $TRUST_FI;
                }
            }
            term SFW44_tlb_traffic {
                from {
                    source-address {
                        $SFW_SERVER_PFX;
                    }
                }
                then {
                    count SFW44_tlb_forward_traffic;
                    routing-instance $TRUST_FI;
                }
            }
            term other_traffic {
                then {
                    count other_traffic;
                    accept;
                }
            }
        }
        filter MX_TLB_LB_UNTRUST {
            term NAPT44_tlb_traffic {
                from {
                    destination-address {
                        $SFW_CLIENT_PFX;
                    }
                }
                then {
                    count SFW44_tlb_return_traffic;
                    routing-instance $UNTRUST_FI;
                }
            }
            term SFW44_tlb_traffic {
                from {
                    destination-address {
                        $SFW_SERVER_PFX;
                    }
                }
                then {
                    count SFW44_tlb_return_traffic;
                    routing-instance $UNTRUST_FI;
                }
            }
            term other_traffic {
                then {
                    count other_traffic;
                    accept;
                }
            }
        }
    }
    family inet6 {
        filter IPv6_MX_TLB_LB_TRUST {
            term NAT64_tlb_traffic_traffic {
                from {
                    source-address {
                        $SFW_CLIENT_V6;
                        $SFW_SERVER_V6;
                    }
                }
                then {
                    count SFW44_tlb_forward_traffic;
                    routing-instance $TRUST_FI;
                }
            }
            term other_traffic {
                then {
                    count other_traffic;
                    accept;
                }
            }
        }
        filter IPv6_MX_TLB_LB_UNTRUST {
            term NAT64_tlb_traffic_traffic {
                from {
                    destination-address {
                        $SFW_CLIENT_V6;
                        $SFW_SERVER_V6;
                    }
                }
