policy-options {
    policy-statement trust_export_policy {
        term 1 {
            from {
                protocol direct;
                route-filter $HC_SRC/32 exact;
                condition srg_sig_route_exist;
            }
            then {
                as-path-prepend "$SRX_AS $SRX_AS $SRX_AS";
                next-hop self;
                accept;
            }
        }
        term 2 {
            from {
                protocol direct;
                route-filter $HC_SRC/32 exact;
            }
            then {
                as-path-prepend $SRX_AS;
                next-hop self;
                accept;
            }
        }
        term 3 {
            then reject;
        }
    }
    policy-statement untrust_export_policy {
        term 1 {
            from {
                protocol static;
                route-filter $NAPT_PREFIX exact;
                condition srg_sig_route_exist;
            }
            then {
                as-path-prepend "$SRX_AS $SRX_AS $SRX_AS";
                next-hop self;
                accept;
            }
        }
        term 2 {
            from {
                protocol static;
                route-filter $NAPT_PREFIX exact;
            }
            then {
                as-path-prepend $SRX_AS;
                next-hop self;
                accept;
            }
        }
        term 3 {
            from {
                protocol static;
                route-filter $NAT64_SRC_PREFIX exact;
                condition srg_sig_route_exist;
            }
            then {
                as-path-prepend "$SRX_AS $SRX_AS $SRX_AS";
                next-hop self;
                accept;
            }
        }
        term 4 {
            from {
                protocol static;
                route-filter $NAT64_SRC_PREFIX exact;
            }
            then {
                as-path-prepend $SRX_AS;
                next-hop self;
                accept;
            }
        }
        term 5 {
            from {
                protocol direct;
                route-filter $HC_SRC/32 exact;
                condition srg_sig_route_exist;
            }
            then {
                as-path-prepend "$SRX_AS $SRX_AS $SRX_AS";
                next-hop self;
                accept;
            }
        }
        term 6 {
            from {
                protocol direct;
                route-filter $HC_SRC/32 exact;
            }
            then {
                as-path-prepend $SRX_AS;
                next-hop self;
                accept;
            }
        }
        term 7 {
            then reject;
        }
    }
    policy-statement mnha_ip {
        term 1 {
            from {
                route-filter $MNHA_NODE/32 exact;
            }
            then {
                next-hop self;
                accept;
            }
        }
        term 2 {
            then reject;
        }
    }
    condition srg_sig_route_exist {
        if-route-exists {
            $SIG_ROUTE/32;
            table MNHA-VR.inet.0;
        }
    }
}

