}

policy-options {
    policy-statement PS-ISIS-EXPORT {
        term OOB-MGMT {
            from interface [ em0.0 fxp0.0 re0:mgmt-0.0 ];
            then reject;
        }
        term LOCAL-LOOPBACK-IPV4 {
            from {
                protocol direct;
                interface lo0.0;
                route-filter $LOOPBACK_V4/32 exact;
            }
            then {
                prefix-segment {
                    index $NODE_SID_V4;
                    node-segment;
                }
                accept;
            }
        }
        term LOCAL-LOOPBACK-IPV6 {
            from {
                protocol direct;
                interface lo0.0;
                route-filter $LOOPBACK_V6/128 exact;
            }
            then {
                prefix-segment {
                    index $NODE_SID_V6;
                    node-segment;
                }
