 * Peers with: n/a
 * Variables: none. Apply-groups in this JVD are entirely
 *            wildcard-driven (e.g. <ae*>, <METRO_*>) and carry
 *            only network-wide constants — there are no per-PE
 *            values to parameterise.
 */
groups {
    GR-L2CKT-HS {
        protocols {
            l2circuit {
                neighbor <*> {
                    interface <*> {
                        pseudowire-status-tlv {
                            hot-standby-vc-on;
                        }
                        switchover-delay 0;
                    }
                }
            }
        }
    }
}

