 */
policy-options {
    prefix-list LOOPBACK {
        $LOOPBACK_V4/32;
        $LOOPBACK_SR_V4/32;
    }
    policy-statement IMPORT-BGP {
        term 1 {
            from {
                prefix-list LOOPBACK;
            }
            then reject;
        }
        term 2 {
            then accept;
        }
    }
}

