 */
routing-options {
    transport-class {
        auto-create;
        name gold {
            color 4000;
            tunnel-egress {
                end-point $TC_EGRESS;
            }
        }
        name bronze {
            color 6000;
            tunnel-egress {
                end-point $TC_EGRESS;
            }
        }
    }
}

