 *   $AC_INTF            e.g. xe-0/1/4.800
 *   $RD                 e.g. 64535:81000
 *   $RT                 e.g. 64535:1183000
 */
routing-instances {
    $INSTANCE_NAME {
        instance-type virtual-switch;
        protocols {
            vpls {
                site $L2VPN_SITE {
                    site-identifier $SITE_ID;
                }
                site-range 10;
                label-block-size 8;
                no-tunnel-services;
            }
        }
        bridge-domains {
            $BD_NAME {
                vlan-id $VLAN_BD;
                interface $AC_INTF;
                bridge-options {
                    no-normalization;
                }
            }
        }
        route-distinguisher $RD;
        vrf-export $INSTANCE_NAME;
        vrf-target target:$RT;
    }
}

